t; }.data-panel-heading h2 { margin: 0 0 4px; font-size: 17px; }.data-panel-heading p { color: #64748b; font-size: 11px; }.data-panel-heading--plain { display: block; }.data-panel-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 14px; color: #64748b; font-size: 11px; }.content-tabs { margin-top: 2px; }.data-state { display: grid; justify-items: center; gap: 7px; padding: 44px 10px; text-align: center; }.data-state strong { color: #334155; font-size: 13px; }.channel-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 9px; margin-top: 17px; }.channel-card { display: flex; align-items: center; gap: 10px; min-width: 0; padding: 12px; text-align: left; border: 1px solid #e5e7eb; border-radius: 10px; color: #1e293b; background: #fff; }.channel-card:hover,.channel-card.selected { border-color: #93c5fd; background: #f8fbff; }.channel-avatar { display: grid; place-items: center; flex: 0 0 auto; width: 34px; height: 34px; border-radius: 9px; color: #1d4ed8; background: #dbeafe; font-weight: 700; }.channel-card__body { display: grid; gap: 2px; min-width: 0; flex: 1; }.channel-card__body strong,.channel-card__body small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.channel-card__body small { color: #64748b; font-size: 10px; }.search-form { gap: 10px; margin-top: 18px; align-items: end; }.search-form label { flex: 0 0 230px; }.search-form .search-keyword { flex: 1; }.message-results { margin-top: 18px; }.message-results__meta { color: #64748b; font-size: 11px; }.message-list { display: grid; gap: 0; margin-top: 9px; border-top: 1px solid #e5e7eb; }.load-more { display: block; margin: 14px auto 0; }.message-item { padding: 13px 2px; border-bottom: 1px solid #e5e7eb; }.message-item time { color: #94a3b8; font-size: 10px; }.message-item p { margin-top: 6px; color: #334155; font-size: 12px; line-height: 1.7; white-space: pre-wrap; overflow-wrap: anywhere; }.spinner { display: inline-block; width: 13px; height: 13px; margin-right: 6px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: spin .8s linear infinite; }@keyframes spin { to { transform: rotate(360deg); } }
@media (max-width: 700px) { .data-panel-toolbar { align-items: stretch; flex-direction: column; }.account-summary { align-items: flex-start; gap: 12px; flex-direction: column; }.qr-flow { grid-template-columns: 1fr; justify-items: center; }.flow-copy { width: 100%; }.channel-grid { grid-template-columns: 1fr; }.search-form { align-items: stretch; flex-direction: column; }.search-form label { flex-basis: auto; width: 100%; }.search-form .button { width: 100%; }.password-row,.step-actions { flex-direction: column; }.password-row button,.step-actions button { width: 100%; } }
